import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Layout blocks","description":"Arrange blocks side by side, organize them into tabs, and guide users through steps.","frontmatter":{"title":"Layout blocks","description":"Arrange blocks side by side, organize them into tabs, and guide users through steps."},"headers":[],"relativePath":"en/seiten/layout-bloecke.md","filePath":"en/seiten/layout-bloecke.md","lastUpdated":1787319236000}'),s={name:"en/seiten/layout-bloecke.md"};function n(d,t,i,l,h,p){return a(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="layout-blocks" tabindex="-1">Layout blocks <a class="header-anchor" href="#layout-blocks" aria-label="Permalink to &quot;Layout blocks&quot;">​</a></h1><p>Four blocks arrange other blocks. They&#39;re the scaffolding for any page that goes beyond a plain sequence of text.</p><table tabindex="0"><thead><tr><th>Block</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Horizontal layout</strong></td><td><em>Arrange blocks side by side</em></td></tr><tr><td><strong>Vertical layout</strong></td><td><em>Arrange blocks stacked</em></td></tr><tr><td><strong>Tab layout</strong></td><td><em>Show sub-pages as tabs</em></td></tr><tr><td><strong>Stepper layout</strong></td><td><em>Show sub-pages as steps</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Work in structure mode</p><p>Once you nest layouts, it&#39;s hard to tell in the regular editor which block sits inside which. Show the <strong>Page structure</strong> panel via <strong>Show structure mode</strong>. → <a href="/en/seiten/seite-erstellen">Creating a page</a></p></div><hr><h2 id="horizontal-and-vertical-layout" tabindex="-1">Horizontal and vertical layout <a class="header-anchor" href="#horizontal-and-vertical-layout" aria-label="Permalink to &quot;Horizontal and vertical layout&quot;">​</a></h2><p>Both work the same way, just in different directions.</p><h3 id="arrangement" tabindex="-1">Arrangement <a class="header-anchor" href="#arrangement" aria-label="Permalink to &quot;Arrangement&quot;">​</a></h3><p>Under <strong>Arrangement</strong>, you set:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Options</th></tr></thead><tbody><tr><td>Direction</td><td><em>Side by side</em> / <em>Stacked</em></td></tr><tr><td>Alignment</td><td><em>Start</em>, <em>Center</em>, <em>End</em>, <em>Top</em>, <em>Bottom</em></td></tr><tr><td>Distribution</td><td><em>Space between</em>, <em>Stretch</em>, <em>Wrap content</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">&quot;Wrap content&quot; for mobile devices</p><p>Without this setting, blocks placed side by side stay side by side even on narrow screens and get squeezed. With <em>Wrap content</em>, they drop below each other when there isn&#39;t enough room.</p><p>Check the result in the Portal preview under <em>Smartphone</em>.</p></div><h3 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h3><p>Also available: <strong>Background color</strong>, <strong>Border radius</strong>, <strong>Width</strong>, and <strong>Height</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Building cards</p><p>A vertical layout with a background color and border radius makes a card. Several of these in a horizontal layout make a row of cards — the standard basis for dashboards.</p></div><hr><h2 id="tab-layout" tabindex="-1">Tab layout <a class="header-anchor" href="#tab-layout" aria-label="Permalink to &quot;Tab layout&quot;">​</a></h2><p>Displays <strong>sub-pages</strong> as tabs.</p><table tabindex="0"><thead><tr><th>Action</th><th>Label</th></tr></thead><tbody><tr><td>Create a page</td><td><strong>Add page</strong></td></tr><tr><td>Remove a page</td><td><strong>Delete selected page</strong></td></tr><tr><td>Reorder</td><td><strong>Move left</strong> / <strong>Move right</strong></td></tr><tr><td>Color</td><td><strong>Tab color</strong></td></tr></tbody></table><p>Without sub-pages, it shows <em>No pages</em> with the note <em>Add pages to see them as tabs</em>.</p><p>If a tab contains incomplete required fields, the editor reports <em>This tab contains validation errors</em>.</p><div class="tip custom-block"><p class="custom-block-title">What tabs are good for</p><p>For sections that are <strong>independent</strong> of each other and can be viewed in any order — &quot;Overview,&quot; &quot;Details,&quot; &quot;Documents.&quot;</p><p>For a process with a defined order, use the Stepper layout instead.</p></div><hr><h2 id="stepper-layout" tabindex="-1">Stepper layout <a class="header-anchor" href="#stepper-layout" aria-label="Permalink to &quot;Stepper layout&quot;">​</a></h2><p>Displays <strong>sub-pages</strong> as a sequence of steps — for guided processes.</p><table tabindex="0"><thead><tr><th>Action</th><th>Label</th></tr></thead><tbody><tr><td>Create a step</td><td><strong>Add step</strong></td></tr><tr><td>Remove a step</td><td><strong>Delete selected step</strong></td></tr><tr><td>Reorder</td><td><strong>Move up</strong> / <strong>Move down</strong></td></tr></tbody></table><p>Without steps: <em>No steps</em> with the note <em>Add steps to see them in the stepper</em>.</p><p>Visitors navigate with <strong>Back</strong> and <strong>Next</strong>.</p><h3 id="two-settings" tabindex="-1">Two settings <a class="header-anchor" href="#two-settings" aria-label="Permalink to &quot;Two settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>Linear</strong></td><td><em>Previous steps must be completed first</em></td></tr><tr><td><strong>Vertical</strong></td><td><em>Show steps in vertical mode</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Linear is for processes, not for forms</p><p><strong>Linear</strong> enforces the order — useful for applications, onboarding, and anything where a later step builds on an earlier one.</p><p>Without <em>Linear</em>, visitors can jump around. That&#39;s more comfortable when the steps are purely for organization.</p></div><p>Incomplete required fields report <em>This step contains validation errors</em>.</p><hr><h2 id="which-layout-for-what" tabindex="-1">Which layout for what <a class="header-anchor" href="#which-layout-for-what" aria-label="Permalink to &quot;Which layout for what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Layout</th></tr></thead><tbody><tr><td>Metrics side by side</td><td><strong>Horizontal layout</strong> with <em>Wrap content</em></td></tr><tr><td>Card with border and color</td><td><strong>Vertical layout</strong> with background color</td></tr><tr><td>Several independent sections</td><td><strong>Tab layout</strong></td></tr><tr><td>Guided process with a fixed order</td><td><strong>Stepper layout</strong>, <em>Linear</em></td></tr><tr><td>Structure without enforcement</td><td><strong>Stepper layout</strong> without <em>Linear</em></td></tr><tr><td>Long text page</td><td>no layouts, just headings</td></tr></tbody></table><h2 id="example-building-a-dashboard" tabindex="-1">Example: building a dashboard <a class="header-anchor" href="#example-building-a-dashboard" aria-label="Permalink to &quot;Example: building a dashboard&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vertical layout</span></span>
<span class="line"><span>├── Heading 1                    &quot;Sales&quot;</span></span>
<span class="line"><span>├── Horizontal layout            (Wrap content enabled)</span></span>
<span class="line"><span>│   ├── Counter                  open inquiries</span></span>
<span class="line"><span>│   ├── Sum card                 order value</span></span>
<span class="line"><span>│   └── Donut chart              by status</span></span>
<span class="line"><span>└── Grid View                    detail table</span></span></code></pre></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/bloecke">Block overview</a></li><li><a href="/en/seiten/seitenlayout">Page layout</a></li><li><a href="/en/seiten/auswertungen">Embedding views and evaluations</a></li></ul>`,38)])])}const b=e(s,[["render",n]]);export{u as __pageData,b as default};
